package studio.solocamera;

/** Authored layouts, palettes and timing; no rendered video packs or remote service. */
final class EditorTitlePresets {
 static final String[] GROUPS={"All","Lower thirds","Titles","Slides","Callouts","Social CTA","Tutorial graphics","Professions"};
 private static final String[] BASE_NAMES={"Studio signature","Editorial line","Broadcast nameplate","Modern capsule","Split identity","Minimal underline","Amber speaker","Ivory editorial","Blue broadcast","Mint capsule","Coral identity","Violet underline","Big statement","Elegant opening","Focus frame","Bold chapter","Quiet luxury","Electric headline","Clean introduction","Documentary title","Key message","Three takeaways","Chapter break","Quote slide","Section agenda","Product spotlight","How it works","Closing message","Lesson summary","Presentation cover","Feature story","Thank-you slide","Pro tip","Important note","Did you know?","Step marker","Quick reminder","Key number","Subscribe card","Watch next"};
 static final String[] NAMES;static{java.util.ArrayList<String> names=new java.util.ArrayList<>(java.util.Arrays.asList(BASE_NAMES));for(int p=0;p<EditorSocialTitles.PLATFORMS.length;p++)for(String action:EditorSocialTitles.ACTIONS[p])names.add(EditorSocialTitles.PLATFORMS[p]+" · "+action);names.addAll(java.util.Arrays.asList(EditorTutorialTitles.NAMES));for(int i=88;i<138;i++)names.add(EditorProfessionTitles.name(i));NAMES=names.toArray(new String[0]);}
 private static final int[] ACCENTS={0xffffc857,0xff66d4e2,0xff8fafff,0xff7ee2bc,0xffff8b79,0xffc5a4ff};
 static int group(int id){return id<12?1:id<20?2:id<32?3:id<40?4:id<76?5:id<88?6:7;}
 static int layout(int id){return id<12?id%6:id<20?6+(id-12)%3:id<32?9+(id-20)%3:3+(id-32)%6;}
 static boolean slide(int id){return group(id)==3||(EditorProfessionTitles.profession(id)&&EditorProfessionTitles.variant(id)==4);}
 static EditorProject.Clip create(int id,long duration){if(id<0||id>=NAMES.length)throw new IllegalArgumentException("Unknown title preset");if(EditorProfessionTitles.profession(id))return EditorProfessionTitles.create(id,duration);EditorProject.Clip c=new EditorProject.Clip("title:preset",NAMES[id],duration);c.titleDesign=id+1;c.text=group(id)==1?"Alex Morgan":group(id)==2?"MAKE YOUR STORY MATTER":slide(id)?"A clear idea.\nA lasting impression.":"One useful idea";c.designSubtitle=group(id)==1?"CREATOR & PRESENTER":slide(id)?"Replace this line with your supporting message.":"Add your supporting message";c.designEyebrow=slide(id)?"YOUR PRESENTATION":group(id)==4?NAMES[id].toUpperCase(java.util.Locale.US):"SOLO STORIES";if(group(id)==2){c.text=new String[]{"MAKE YOUR STORY MATTER","The art of telling stories","A fresh perspective","CHAPTER ONE","Less noise. More meaning.","IDEAS IN MOTION","Welcome to the conversation","Behind the story"}[id-12];}else if(slide(id)){c.text=new String[]{"One idea. A clear direction.","Three things to remember","CHAPTER 01","Great stories begin with curiosity.","Today’s agenda","Designed to make life simpler","A simple process","Let’s build something great","What we learned","YOUR NEXT BIG IDEA","The story behind the work","Thank you for watching"}[id-20];c.designSubtitle=new String[]{"Introduce the central message of your presentation.","01  Start with a clear goal.\n02  Focus on your audience.\n03  End with the next step.","Introduce your next topic or lesson here.","Add the author or source of your quotation.","Introduction  /  Key ideas  /  Next steps","Describe the benefit that matters most.","Plan your idea. Create your story. Share your work.","Invite your audience to take the next step.","Summarize the most useful takeaway here.","Your presentation title and supporting message.","Introduce the person, product or idea behind your story.","Add your channel name or contact details."}[id-20];}else if(group(id)==4){c.text=new String[]{"Keep it simple.","Before you begin","A fresh perspective","STEP 01","Remember this","Make the number matter","Join the conversation","Keep exploring"}[id-32];c.designSubtitle=new String[]{"One message. One clear takeaway.","Add the detail your audience should not miss.","Share a useful fact or discovery.","Describe the next action clearly.","A short reminder goes a long way.","Add context that makes your statistic useful.","Follow for more useful ideas.","Introduce the next video or lesson."}[id-32];}c.designAccent=ACCENTS[id%ACCENTS.length];boolean light=id%6==1||id%6==4;c.textBackground=light?0xfff6f1e8:0xff121e2b;c.textColor=light?0xff172838:0xfff7f7f4;c.backgroundEnabled=true;c.backgroundRadius=16;c.textSize=slide(id)?82:group(id)==2?90:54;c.font=id%4==1?"font:playfairdisplay":id%4==2?"font:bebasneue":"font:inter";c.bold=id%4!=1;c.alignment=0;c.textPlaced=true;c.textY=group(id)==1?-.50:group(id)==4?-.2:0;c.textX=0;animate(c,duration,1);if(EditorSocialTitles.social(id))EditorSocialTitles.configure(c,id,duration);if(id>=76)EditorTutorialTitles.configure(c,id,duration);return c;}
 static void animate(EditorProject.Clip c,long duration,int motion){c.titleMotion=Math.max(0,Math.min(3,motion));}
 /** Add authored entrance/exit offsets to the independent object placement. */
 static void motion(EditorProject.Clip c,long at,long length,EditorMotion.Key pose){if(c.titleDesign==0||c.titleMotion==0)return;long duration=Math.max(200,length),ease=Math.min(550,duration/4);double in=EditorProject.bound(at/(double)Math.max(1,ease),0,1),out=EditorProject.bound((duration-at)/(double)Math.max(1,ease),0,1);EditorMotion.Key curve=new EditorMotion.Key();curve.x1=.16;curve.y1=1;curve.x2=.3;curve.y2=1;in=EditorMotion.ease(curve,in);pose.alpha*=in*out;if(c.titleMotion==1)pose.y-=.05*(1-in);else if(c.titleMotion==2)pose.x+=-.12*(1-in)+.10*(1-out);else if(c.titleMotion==3)pose.scale*=(.88+.12*in)*(.95+.05*out);}
 /** Recognize only the old authored four-key skeleton. Keep additional user keys. */
 static void migrate(EditorProject.Clip c){if(c.titleDesign==0||c.keys.size()<4)return;EditorMotion.Key first=c.keys.get(0),last=c.keys.get(c.keys.size()-1);if(first.at!=0||Math.abs(first.alpha)>1e-6||Math.abs(last.alpha)>1e-6||Math.abs(first.x1-.16)>1e-6||Math.abs(first.y1-1)>1e-6||Math.abs(first.x2-.3)>1e-6)return;EditorMotion.Key enter=null,hold=null;long ease=Math.min(550,last.at/4);for(EditorMotion.Key k:c.keys){if(k.at==ease)enter=k;if(k.at==Math.max(ease+1,last.at-ease))hold=k;}if(enter==null||hold==null||Math.abs(enter.alpha-1)>1e-6||Math.abs(hold.alpha-1)>1e-6||Math.abs(enter.x-hold.x)>1e-6||Math.abs(enter.y-hold.y)>1e-6||Math.abs(enter.scale-1)>1e-6||Math.abs(hold.scale-1)>1e-6)return;c.titleMotion=Math.abs(first.scale-.88)<1e-6?3:Math.abs(first.x-enter.x+.12)<1e-6?2:1;c.textX=enter.x;c.textY=enter.y;c.textPlaced=true;c.keys.remove(first);c.keys.remove(enter);c.keys.remove(hold);c.keys.remove(last);}
}
